const t={ui:{fig:"Abb. 1",title:"Kosmetiktasche · Anatomie",svgLabel:"Eine isometrische Zeichnung der gefütterten Kosmetiktasche mit Reißverschluss und runden Ecken und wie sie Schritt für Schritt genäht wird.",prev:"Vorheriger Schritt",dot:(e,n)=>e?`Schritt ${e}: ${n}`:n,start:"Schritte →",next:"Weiter →",overview:"Übersicht",stepOf:(e,n)=>`Schritt ${e} von ${n}`,machine:e=>`Maschine: ${e}`,inThisStep:"In diesem Schritt",takeApart:"Zerlegen",putTogether:"Zusammensetzen",replay:"↻ Noch einmal",parts:"Teile",allSteps:"Schritt-für-Schritt-Anleitung",endView:"QUERSCHNITT",cutTitle:"Kosmetiktasche · Zuschnittmaße",cutAlt:"Zuschnittplan für eine gefütterte Kosmetiktasche mit Reißverschluss: Außenteil und Futter je 23 × 31 cm, dünne Bügeleinlage 21 × 29 cm, vier rosa Teile 18 × 10 cm, ein Quadrat Bügeleinlage 16 × 16 cm für die runden Ecken und ein Reißverschluss von 20 cm.",cutCaption:"Alle Zuschnitte mit ihren Maßen – wie in Schritt 1."},stitches:{straight:"Geradstich"},labels:{cm23:"23 cm",cm31:"31 cm",cm29:"29 cm",cm21:"21 cm",cm18:"18 cm",cm10:"10 cm",cm16:"16 cm",cm20:"20 cm",cm1:"1 cm",cm35:"3,5 cm",cm25:"2,5 cm",outerCotton:"außen · Baumwolle",liningCotton:"Futter · gleich groß",ifaceThin:"dünne Einlage",pink4:"4 × rosa",ifaceCorners:"für die Ecken",zipper:"Reißverschluss",radius8:"Radius 8 cm",paperTemplate:"Papierschablone",cutInHalf:"halbieren",twoHalves:"zwei Halbkreise",ironOn:"aufbügeln",rightSides:"rechts auf rechts",alongEdge:"an der Kante nähen",makeTwo:"zwei davon",trimNotch:"kürzen, einschneiden",turnOut:"auf rechts wenden",wrongSideUp:"außen, linke Seite oben",edges1:"1 cm vom Rand",middleBottom:"Mitte = Boden",rightSideUp:"rechte Seite oben",onBottomLine:"auf der Bodenlinie",stitchRound:"rundum feststeppen",straight05:"gerade Seite: 0,5 cm",outerUp:"außen, rechts nach oben",zipperDown:"RV rechts nach unten",liningDown:"Futter rechts nach unten",seam05:"Naht 0,5 cm",liningAway:"Futter wegklappen",foldBoth:"beide falten",otherSide:"die andere Seite",openZipper:"RV öffnen",opening6:"6 cm Wendeöffnung",outerHalf:"außen",liningHalf:"Futter",cutCorners:"Ecken ausschneiden",pinchSew:"auffalten, quer nähen",seamOnFold:"Naht auf den Bruch",allFour:"alle vier Ecken",turnThrough:"durch die Öffnung wenden",byHand:"von Hand schließen",pushLining:"Futter hineinschieben",closeZip:"RV schließen"},steps:[{title:"Die fertige Kosmetiktasche",text:"Eine gefütterte Kosmetiktasche mit Reißverschluss für Make-up, Stifte, Tuben und Cremes: bedruckte Baumwolle mit dünner Einlage und an jedem Ende des Bodens eine runde rosa Ecke. Tippe auf die Tasche, um sie zu zerlegen."},{title:"Zuschneiden",text:"Außenteil und Futter: je 23 × 31 cm. Dünne Bügeleinlage: 21 × 29 cm und ein Quadrat von 16 × 16 cm. Vier rosa Teile, 18 × 10 cm. Ein Reißverschluss von 20 cm.",details:["Schneide aus bedruckter Baumwolle das Außenteil zu, 23 × 31 cm. Das Futter ist genauso groß, 23 × 31 cm.","Schneide aus dünner Bügeleinlage ein Teil von 21 × 29 cm für das Außenteil und ein Quadrat von 16 × 16 cm für die runden Ecken zu.","Schneide aus rosa Baumwolle vier Teile von 18 × 10 cm zu – zwei für jede Ecke.","Außerdem brauchst du einen Reißverschluss von 20 cm.","Alle Nahtzugaben dieser Tasche sind 0,5 cm."]},{title:"Schablone für die Ecken",text:"Zeichne einen Kreis mit 8 cm Radius auf Papier und schneide ihn aus. Übertrage ihn auf das Quadrat Einlage von 16 cm, schneide den Kreis aus und halbiere ihn.",details:["Mach eine Papierschablone: einen Kreis mit einem Radius von 8 cm.","Übertrage den Kreis auf das Quadrat Bügeleinlage von 16 × 16 cm und schneide ihn aus.","Halbiere den Kreis: zwei Halbkreise, einer für jede runde Ecke."]},{title:"Halbmonde nähen",text:"Bügle einen Halbkreis auf die linke Seite eines rosa Teils – mittig, die gerade Seite 1 cm von der langen Kante. Leg ein zweites rosa Teil rechts auf rechts darunter und nähe an der runden Kante der Einlage entlang.",details:["Leg einen Halbkreis Einlage mit der Klebeseite nach unten auf die linke Seite eines rosa Teils: mittig, die gerade Seite 1 cm von einer langen Kante. Bügle ihn auf.","Leg es rechts auf rechts auf ein zweites rosa Teil.","Nähe an der Rundung entlang – genau an der Kante der Einlage.","Den zweiten Halbmond nähst du genauso."]},{title:"Zurückschneiden und wenden",text:"Schneide den Stoff an der Rundung zurück, schneide die Nahtzugabe ein und wende jeden Halbmond auf rechts. Bügle ihn.",details:["Schneide den überstehenden Stoff an der Rundung weg und lass eine schmale Nahtzugabe stehen.","Schneide die Nahtzugabe an der Rundung ein, damit sie flach liegt.","Wende beide Halbmonde durch die gerade Seite auf rechts und bügle sie. Die gerade Seite bleibt offen."]},{title:"Einlage aufbügeln",text:"Bügle die Einlage von 21 × 29 cm auf die linke Seite des Außenteils, 1 cm von jeder Kante. Falte das Außenteil in der Mitte und markiere die Mitte mit kleinen Einschnitten: Das ist der Boden.",details:["Leg das Außenteil mit der linken Seite nach oben.","Leg die Einlage mit der Klebeseite nach unten darauf, 1 cm von jeder Kante, und bügle sie auf. Das Futter bekommt keine Einlage.","Falte das Außenteil quer in der Mitte und schneide an beiden Enden des Bruchs kleine Markierungen ein. Der Bruch ist der Boden der Tasche – dort gibt es keine Naht."]},{title:"Halbmonde aufnähen",text:"Leg auf die rechte Seite des Außenteils an jede Seitenkante einen Halbmond – die Mitte auf der Bodenlinie, die gerade Kante bündig mit der Seite – und steppe ihn rundum fest.",details:["Dreh das Außenteil mit der rechten Seite nach oben.","Leg an jede Seitenkante einen Halbmond: die gerade offene Kante bündig mit der Seitenkante des Außenteils, die Mitte auf den Markierungen – der Bodenlinie.","Steppe jeden rundum fest: an der Rundung genau an der Kante, an der geraden Seite 0,5 cm von der Kante. Die gerade Seite kommt später in die Seitennaht."]},{title:"Reißverschluss: erste Seite",text:"Außenteil mit der rechten Seite nach oben, darauf mittig an einer kurzen Seite den Reißverschluss mit der rechten Seite nach unten, darüber das Futter mit der rechten Seite nach unten. Nähe 0,5 cm von der Kante.",details:["Leg das Außenteil mit der rechten Seite nach oben.","Leg den Reißverschluss mit der rechten Seite nach unten mittig an eine Seite von 23 cm: Seine Enden reichen nicht bis an die Seitenkanten, damit sie nicht in die Seitennähte kommen.","Leg das Futter mit der rechten Seite nach unten darauf, Kante auf Kante mit dem Außenteil.","Nähe durch alle Lagen, 0,5 cm von der Kante. Am Reißverschluss wird nicht abgesteppt."]},{title:"Reißverschluss: zweite Seite",text:"Klapp das Futter vom Reißverschluss weg. Falte das Außenteil und das Futter jeweils in der Mitte, sodass ihre anderen kurzen Seiten an die andere Seite des Reißverschlusses kommen, und nähe sie genauso an.",details:["Klapp das Futter vom Reißverschluss weg.","Falte das Außenteil auf der Bodenlinie rechts auf rechts, das Futter genauso.","Ihre anderen kurzen Seiten treffen jetzt auf die andere Seite des Reißverschlusses: Außenteil, Reißverschluss mit der rechten Seite nach unten, Futter – wie beim ersten Mal.","Nähe 0,5 cm von der Kante. Außenteil und Futter sind jetzt ein Ring."]},{title:"Seitennähte",text:"Öffne den Reißverschluss. Leg die Tasche flach, Außenteil auf Außenteil und Futter auf Futter, rechts auf rechts, und nähe beide Seiten – mit einer Wendeöffnung von 6 cm in der Mitte einer Futterseite.",details:["Öffne zuerst den Reißverschluss: Durch ihn wird die Tasche später gewendet.","Leg sie flach: das Außenteil rechts auf rechts auf der einen Seite des Reißverschlusses, das Futter auf der anderen.","Nähe beide Seitennähte 0,5 cm von der Kante – durch die Halbmonde mit.","Lass in einer Seite des Futters 6 cm offen, in der Mitte der Naht."]},{title:"Boden: Ecken nähen",text:"Schneide aus jeder unteren Ecke – zwei am Außenteil, zwei am Futter – ein Stück von 3,5 × 2,5 cm aus: 3,5 cm entlang des Bodens, 2,5 cm entlang der Seitennaht. Falte jede Ecke auf und nähe quer darüber.",details:["Zeichne in jede der vier unteren Ecken ein Rechteck von 3,5 × 2,5 cm: 3,5 cm entlang des Bodens, 2,5 cm entlang der Seitennaht.","Schneide sie aus.","Falte jede Ecke so auf, dass die Seitennaht auf dem Bodenbruch liegt und die Schnittkanten eine gerade Linie bilden.","Nähe quer darüber, 0,5 cm von der Kante. So alle vier Ecken."]},{title:"Wenden",text:"Wende die Tasche durch die Öffnung im Futter und den offenen Reißverschluss auf rechts. Schließe die Öffnung von Hand, schieb das Futter hinein und schließ den Reißverschluss.",details:["Zieh das Außenteil durch die Öffnung im Futter und den offenen Reißverschluss.","Schlag die Kanten der Öffnung nach innen ein und nähe sie von Hand zu.","Schieb das Futter in die Tasche, bis in die Ecken, und schließ den Reißverschluss. Aus den Halbmonden sind runde rosa Ecken geworden."]}],legend:[{title:"Außenteil",text:"bedruckte Baumwolle · 23 × 31 cm, in der Mitte gefaltet: Der Bruch ist der Boden"},{title:"Einlage",text:"dünn, zum Aufbügeln · 21 × 29 cm, auf dem Außenteil, 1 cm vom Rand"},{title:"Runde Ecken ×2",text:"vier rosa Teile 18 × 10 cm · Halbkreise aus Einlage, Radius 8 cm, aus einem Quadrat von 16 × 16 cm"},{title:"Reißverschluss",text:"20 cm · mittig an den kurzen Seiten, nicht abgesteppt"},{title:"Futter",text:"Baumwolle · 23 × 31 cm, ohne Einlage"},{title:"Nähte",text:"alle 0,5 cm · eine Wendeöffnung von 6 cm im Futter, von Hand geschlossen · Ecken: 3,5 × 2,5 cm ausgeschnitten"}]};export{t as default};
